import{_ as h,o as t,c,a0 as a}from"./chunks/framework.DCluYYrN.js";const r=JSON.parse('{"title":"Cứu khỏi bootloop (Vòng lặp khởi động)","description":"","frontmatter":{},"headers":[],"relativePath":"vi_VN/guide/rescue-from-bootloop.md","filePath":"vi_VN/guide/rescue-from-bootloop.md"}'),i={name:"vi_VN/guide/rescue-from-bootloop.md"};function o(s,n,e,g,l,p){return t(),c("div",null,[...n[0]||(n[0]=[a(`<h1 id="cuu-khoi-bootloop-vong-lap-khoi-đong" tabindex="-1">Cứu khỏi bootloop (Vòng lặp khởi động) <a class="header-anchor" href="#cuu-khoi-bootloop-vong-lap-khoi-đong" aria-label="Permalink to &quot;Cứu khỏi bootloop (Vòng lặp khởi động)&quot;">​</a></h1><p>Khi flash một thiết bị, chúng ta có thể gặp phải tình trạng máy &quot;bị brick&quot;. Về lý thuyết, nếu bạn chỉ sử dụng fastboot để flash phân vùng boot hoặc cài đặt các mô-đun không phù hợp khiến máy không khởi động được thì điều này có thể được khắc phục bằng các thao tác thích hợp. Tài liệu này nhằm mục đích cung cấp một số phương pháp khẩn cấp để giúp bạn khôi phục từ thiết bị &quot;bị brick&quot;.</p><h2 id="brick-boi-flash-vao-phan-vung-boot" tabindex="-1">Brick bởi flash vào phân vùng boot <a class="header-anchor" href="#brick-boi-flash-vao-phan-vung-boot" aria-label="Permalink to &quot;Brick bởi flash vào phân vùng boot&quot;">​</a></h2><p>Trong KernelSU, các tình huống sau có thể gây ra lỗi khởi động khi flash phân vùng khởi động:</p><ol><li>Bạn flash image boot sai định dạng. Ví dụ: nếu định dạng khởi động điện thoại của bạn là <code>gz</code>, nhưng bạn flash image định dạng <code>lz4</code> thì điện thoại sẽ không thể khởi động.</li><li>Điện thoại của bạn cần tắt xác minh AVB để khởi động bình thường (thường yêu cầu xóa tất cả dữ liệu trên điện thoại).</li><li>Kernel của bạn có một số lỗi hoặc không phù hợp để flash điện thoại của bạn.</li></ol><p>Bất kể tình huống thế nào, bạn có thể khôi phục bằng cách <strong>flash boot image gốc</strong>. Do đó, khi bắt đầu hướng dẫn cài đặt, chúng tôi thực sự khuyên bạn nên sao lưu boot image gốc trước khi flash. Nếu chưa sao lưu, bạn có thể lấy boot image gốc từ người dùng khác có cùng thiết bị với bạn hoặc từ chương trình cơ sở chính thức (official firmware).</p><h2 id="brick-boi-mo-đun" tabindex="-1">Brick bởi mô-đun <a class="header-anchor" href="#brick-boi-mo-đun" aria-label="Permalink to &quot;Brick bởi mô-đun&quot;">​</a></h2><p>Việc cài đặt mô-đun có thể là nguyên nhân phổ biến hơn khiến thiết bị của bạn bị brick, nhưng chúng tôi phải nghiêm túc cảnh báo bạn: <strong>Không cài đặt mô-đun từ các nguồn không xác định</strong>! Vì các mô-đun có đặc quyền root nên chúng có thể gây ra thiệt hại không thể khắc phục cho thiết bị của bạn!</p><h3 id="mo-đun-binh-thuong" tabindex="-1">Mô-đun bình thường <a class="header-anchor" href="#mo-đun-binh-thuong" aria-label="Permalink to &quot;Mô-đun bình thường&quot;">​</a></h3><p>Nếu bạn đã flash một mô-đun đã được chứng minh là an toàn nhưng khiến thiết bị của bạn không khởi động được thì tình huống này có thể dễ dàng phục hồi trong KernelSU mà không phải lo lắng gì. KernelSU tích hợp Chế độ an toàn để giải cứu thiết bị của bạn:</p><h4 id="volume-down" tabindex="-1">Cứu bằng cách nhấn Giảm âm lượng <a class="header-anchor" href="#volume-down" aria-label="Permalink to &quot;Cứu bằng cách nhấn Giảm âm lượng {#volume-down}&quot;">​</a></h4><p>Bạn có thể thử sử dụng <strong>Chế độ an toàn</strong> để giải cứu thiết bị của mình. Sau khi vào Chế độ an toàn, tất cả các mô-đun đều bị tắt.</p><p>Có hai cách để vào Chế độ an toàn:</p><ol><li>Chế Độ An Toàn tích hợp (built-in Safe Mode) của một số hệ thống; một số hệ thống có Chế độ an toàn tích hợp có thể được truy cập bằng cách nhấn và giữ nút giảm âm lượng, trong khi những hệ thống khác (chẳng hạn như MIUI/HyperOS) có thể bật Chế Độ An Toàn trong Recovery. Khi vào Chế Độ An Toàn của hệ thống, KernelSU cũng sẽ vào Chế Độ An Toàn và tự động tắt các mô-đun.</li><li>Chế Độ An Toàn tích hợp (built-in Safe Mode) của KernelSU; phương pháp thao tác là <strong>nhấn phím giảm âm lượng liên tục hơn ba lần</strong> sau màn hình khởi động đầu tiên. Lưu ý là nhấn-thả, nhấn-thả, nhấn-thả chứ không phải nhấn giữ.</li></ol><p>Sau khi vào chế độ an toàn, tất cả các mô-đun trên trang mô-đun của KernelSU Manager đều bị tắt nhưng bạn có thể thực hiện thao tác &quot;gỡ cài đặt&quot; để gỡ cài đặt bất kỳ mô-đun nào có thể gây ra sự cố.</p><p>Chế độ an toàn tích hợp được triển khai trong kernel, do đó không có khả năng thiếu các sự kiện chính do bị chặn. Tuy nhiên, đối với các hạt nhân không phải GKI, có thể cần phải tích hợp mã thủ công và bạn có thể tham khảo tài liệu chính thức để được hướng dẫn.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU đăng ký bộ lắng nghe phím âm lượng trong quá trình khởi tạo mô-đun hạt nhân (được tải khi hạt nhân thực thi quy trình init ở chế độ LKM), và hủy đăng ký ở giai đoạn <code>on_post_fs_data</code> (trước hoạt ảnh khởi động). Bạn cần nắm bắt thời gian và nhanh chóng nhấn phím giảm âm lượng ba lần sau màn hình khởi động đầu tiên. Nếu thiết bị khởi động nhanh hoặc thao tác không kịp thời, chế độ an toàn có thể không được kích hoạt.</p><p>Nếu mô-đun viết mã không hợp lý trong initrc khiến thiết bị không thể khởi động, những mã này vẫn sẽ được thực thi ngay cả trong chế độ an toàn.</p></div><h4 id="manual-rescue" tabindex="-1">Cứu Hộ Thủ Công <a class="header-anchor" href="#manual-rescue" aria-label="Permalink to &quot;Cứu Hộ Thủ Công {#manual-rescue}&quot;">​</a></h4><p>Khi chế độ an toàn không thể giải quyết vấn đề, bạn có thể thử cứu hộ thủ công. Chọn các phương pháp sau tùy theo trạng thái của thiết bị.</p><p><strong>Phương pháp 1: Sử dụng ksud để quản lý các mô-đun thông qua ADB</strong></p><p>Nếu thiết bị có thể lấy root shell thông qua ADB, bạn có thể sử dụng dòng lệnh <code>ksud</code> trực tiếp để vô hiệu hóa hoặc gỡ cài đặt mô-đun có vấn đề:</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sau khi gắn kết các phân vùng <code>metadata</code> và <code>data</code>, bạn có thể chạy lệnh <code>/data/adb/ksud</code> dưới chế độ Recovery để quản lý các mô-đun.</p><p>Vì các thiết bị GKI chia sẻ <code>init</code>, mô-đun hạt nhân KernelSU vẫn sẽ được tải dưới chế độ Recovery, bạn sẽ có thể sử dụng hầu hết các tính năng của <code>ksud</code> (như cài đặt tính năng) một cách bình thường.</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb shell</span></span>
<span class="line"><span>su</span></span>
<span class="line"><span>ksud module list          # Liệt kê tất cả các mô-đun</span></span>
<span class="line"><span>ksud module disable &lt;id&gt;  # Vô hiệu hóa mô-đun có vấn đề</span></span>
<span class="line"><span>ksud module uninstall &lt;id&gt; # Hoặc gỡ cài đặt trực tiếp</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p><strong>Phương pháp 2: Dọn dẹp thủ công thông qua Recovery</strong></p><p>Nếu bạn không thể vào hệ thống (ngay cả ADB cũng không thể kết nối), bạn cần một Recovery của bên thứ ba (chẳng hạn như TWRP) trên thiết bị.</p><p>Việc tải mô-đun của KernelSU phụ thuộc vào tệp chèn init.rc ở phía hạt nhân và tiến trình ksud trong không gian người dùng. Sau khi xóa các tệp này và khởi động lại, KernelSU sẽ không tải bất kỳ mô-đun nào.</p><p><strong>Các bước thao tác:</strong></p><ol><li>Vào Recovery (chẳng hạn như TWRP).</li><li>Gắn kết phân vùng data:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /data</span></span></code></pre></div>(Bạn có thể cần giải mã phân vùng data trước. Thao tác cụ thể tùy thuộc vào thiết bị và phương pháp giải mã.)</li><li>Xóa ksud để ngăn chặn tải mô-đun:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f /data/adb/ksud</span></span></code></pre></div></li><li>(Tùy chọn) Gắn kết phân vùng metadata và xóa tệp chèn init.rc do mô-đun tạo ra:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /metadata</span></span>
<span class="line"><span>rm -f /metadata/ksu/modules.rc</span></span>
<span class="line"><span>rm -f /metadata/watchdog/ksu/modules.rc</span></span></code></pre></div></li><li>Khởi động lại thiết bị:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div></li></ol><p>KernelSU sẽ bỏ qua việc tải tất cả các mô-đun sau khi khởi động lại. Sau khi vào hệ thống, bạn có thể mở lại trình quản lý KernelSU để xử lý các vấn đề của mô-đun.</p><h3 id="đinh-dang-du-lieu-hoac-cac-mo-đun-đoc-hai-khac" tabindex="-1">Định dạng dữ liệu hoặc các mô-đun độc hại khác <a class="header-anchor" href="#đinh-dang-du-lieu-hoac-cac-mo-đun-đoc-hai-khac" aria-label="Permalink to &quot;Định dạng dữ liệu hoặc các mô-đun độc hại khác&quot;">​</a></h3><p>Nếu các phương pháp trên không thể cứu được thiết bị của bạn thì rất có thể mô-đun bạn cài đặt có hoạt động độc hại hoặc đã làm hỏng thiết bị của bạn thông qua các phương tiện khác. Trong trường hợp này, chỉ có hai gợi ý:</p><ol><li>Xóa sạch dữ liệu và flash hệ thống chính thức hoàn toàn.</li><li>Tham khảo dịch vụ hậu mãi.</li></ol>`,32)])])}const d=h(i,[["render",o]]);export{r as __pageData,d as default};
